STOP_WORDS = {
    "show", "make", "build", "create", "with", "and", "the", "for",
    "from", "into", "physics", "simulation", "model", "three", "3d",
    "lab", "interactive", "adjustable", "live", "real", "time",
}


def match_50_physics_model(prompt: str) -> Optional[Dict[str, Any]]:
    """
    Matches a natural-language user prompt against the 50 canonical physics models.
    Supports explicit model numbers (e.g., "14", "#14", "model 14", "14. Chaotic...")
    and multi-keyword weighted scoring across all 50 models.
    """
    if not prompt or not prompt.strip():
        return None
    text = prompt.lower().strip()

    # 1. Explicit model number match: "#14", "model 14", or starting with "14." / "14 "
    explicit = re.search(r"(?:^|\b)(?:model\s*#?|#)(\d{1,2})\b|^(\d{1,2})(?:\.|\b)", text)
    if explicit:
        num = int(explicit.group(1) or explicit.group(2))
        if 1 <= num <= 50:
            for item in CATALOG_50_MODELS:
                if item["id"] == num:
                    return {
                        "model": item,
                        "score": 100,
                        "matched_keywords": [f"#{num}"],
                    }

    # 2. Score all 50 models by keyword phrases and title tokens
    best_item = None
    best_score = 0
    best_matched: List[str] = []

    words = [w for w in re.split(r"[^a-z0-9-]+", text) if len(w) > 2 and w not in STOP_WORDS]

    for item in CATALOG_50_MODELS:
        score = 0
        matched: List[str] = []
        title_lower = item["title"].lower()

        for kw in item["keywords"]:
            kw_lower = kw.lower()
            if kw_lower in text:
                if " " not in kw_lower and len(kw_lower) <= 4:
                    if not re.search(rf"\b{re.escape(kw_lower)}\b", text):
                        continue
                weight = 14 if " " in kw_lower else 7
                score += weight
                matched.append(kw)

        for w in words:
            if re.search(rf"\b{re.escape(w)}\b", title_lower):
                score += 3
                if w not in matched:
                    matched.append(w)

        if score > best_score:
            best_score = score
            best_item = item
            best_matched = matched

    if best_item and best_score >= 5:
        return {
            "model": best_item,
            "score": best_score,
            "matched_keywords": best_matched[:5],
        }
    return None


def load_model_html(model_code: str) -> Optional[str]:
    """Loads the standalone 3D Three.js HTML file for a given model_XX code."""
    html_path = PRESETS_DIR / f"{model_code}.html"
    if html_path.exists():
        return html_path.read_text(encoding="utf-8").replace("\u20d7", "")
    return None
